    /* Persist the replication ID / offset in the base file, so that the
     * AOF base always reflects the replication identity the instance is
     * reporting at the time of the rewrite. Passing a NULL rdbSaveInfo
     * here would silently drop the repl-id / repl-offset aux fields. */
    rdbSaveInfo rsi, *rsiptr;
    rsiptr = rdbPopulateSaveInfo(&rsi);
    if (rsiptr == NULL) {
        /* Not in any replication chain (no backlog and no master): 'rsi'
         * has still been initialized by rdbPopulateSaveInfo(). A stream db
         * of 0 is safe, as the next write command emits its own SELECT. */
        rsi.repl_stream_db = 0;
        rsiptr = &rsi;
    }
    if (rdbSaveRio(SLAVE_REQ_NONE,&aof,&error,RDBFLAGS_AOF_PREAMBLE,rsiptr) == C_ERR) {
        errno = error;
        goto werr;
